# OpenLineage với Airflow: tự động emit lineage
# airflow.cfg:
# [lineage]
# backend = airflow.lineage.backend.atlas.AtlasBackend
# Hoặc dùng OpenLineage provider:
# pip install apache-airflow-providers-openlineage

from airflow import DAG
from airflow.providers.openlineage.extractors import BaseExtractor
from openlineage.client import OpenLineageClient
from openlineage.client.run import RunEvent, RunState, Job, Run
from datetime import datetime
import uuid

# Manual lineage emission cho custom task
def emit_lineage_event(
    job_name: str,
    input_datasets: list[dict],
    output_datasets: list[dict],
    run_id: str = None,
):
    """
    Emit OpenLineage event để catalog lineage.
    Format: namespace://dataset_name
    """
    client = OpenLineageClient(
        url='http://marquez:5000',
        options={'api_key': 'secret'}
    )

    from openlineage.client.facet import (
        SchemaDatasetFacet, SchemaField,
        DataSourceDatasetFacet,
        SqlJobFacet,
    )
    from openlineage.client.run import Dataset

    inputs = [
        Dataset(
            namespace=d['namespace'],
            name=d['name'],
            facets={
                'schema': SchemaDatasetFacet(fields=[
                    SchemaField(name=f['name'], type=f['type'])
                    for f in d.get('fields', [])
                ])
            }
        ) for d in input_datasets
    ]

    outputs = [
        Dataset(namespace=d['namespace'], name=d['name'])
        for d in output_datasets
    ]

    event = RunEvent(
        eventType=RunState.COMPLETE,
        eventTime=datetime.utcnow().isoformat() + 'Z',
        run=Run(runId=run_id or str(uuid.uuid4())),
        job=Job(namespace='data-engineering', name=job_name),
        inputs=inputs,
        outputs=outputs,
    )
    client.emit(event)

# GDPR: tìm tất cả nơi PII của user tồn tại
def find_pii_locations(user_id: str) -> list[str]:
    """
    Query DataHub API để trace lineage của user PII.
    """
    import requests
    # DataHub GraphQL query để tìm lineage
    query = '''
    query findPII($userId: String!) {
        search(input: {
            type: DATASET,
            query: $userId,
            filters: [{field: "tag", value: "pii"}]
        }) {
            searchResults {
                entity {
                    ... on Dataset { urn name }
                }
            }
        }
    }
    '''
    response = requests.post(
        'http://datahub:8080/api/graphql',
        json={'query': query, 'variables': {'userId': user_id}},
        headers={'Authorization': 'Bearer token'},
    )
    return [r['entity']['name'] for r in response.json()['data']['search']['searchResults']]
